        key_differences_vi=["IM có mốc 'trước – nay' nhưng chưa có tiến trình.", "IH kể theo giai đoạn và giải thích lý do thay đổi.", "AL biến tiến trình thành câu chuyện có ý nghĩa cá nhân, tổng kết bằng một nhận định sâu."],
        not_memorize_vi="Không cần có anh trai hay K-pop. Điều cần học là cách chia mốc thời gian và giải thích vì sao bạn thay đổi.",
        personalize_vi="Viết 3 mốc: lúc bắt đầu thích nhạc, một giai đoạn thay đổi, hiện tại. Mỗi mốc 1 chi tiết + 1 lý do.",
        follow_ups=["Is there a song that reminds you of your childhood?", "Have you ever been to a concert?"],
